#pragma once

#include "contrib/gpu/src/common/codec_decode_planning.hpp"
#include "openzl/cpp/poly/Span.hpp"

namespace openzl::gpu {

/**
 * Plans the stream regenerated by constant expansion.
 *
 * @p codec supplies the constant transform identity and staged varint output
 * count. @p inputs must contain exactly one constant value. @p outputs must
 * contain exactly one slot; that slot is unchanged on error.
 *
 * This function validates and derives output properties only.
 *
 * @returns The regenerated output count, which is one, or an error.
 */
ZL_Report planConstantOutputs(
        const CodecDecodePlanningContext& codec,
        poly::span<const StreamPlanningInput> inputs,
        poly::span<CodecDecodeOutputPlan> outputs,
        ZL_OperationContext* opCtx);

} // namespace openzl::gpu
